package dev.interview.orders.fulfillment;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.interview.orders.order.*; import dev.interview.orders.outbox.*; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class FulfillmentConsumerTest {@Test void duplicateEventIsIgnored()throws Exception{var orders=mock(OrderRepository.class);var processed=mock(ProcessedEventRepository.class);var id=UUID.randomUUID();var orderId=UUID.randomUUID();when(processed.existsById(id)).thenReturn(true);var consumer=new FulfillmentConsumer(new ObjectMapper(),orders,processed);assertThat(consumer.consume("{\"eventId\":\""+id+"\",\"orderId\":\""+orderId+"\"}")).isEqualTo(orderId);verifyNoInteractions(orders);}}
